  /**
   * Class representing a chart series.
   *
   * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiChartSeries/
   */
  export interface ApiChartSeries {
    /**
     * Tries to change the series type. Returns true if successful.
     *
     * @param sType - Chart type.
     *
     * @example
     * ```js
     * // How do I change one series in a combined chart to a new chart style in a spreadsheet?
     *
     * // Convert a single series from one chart style to another within the same chart in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * worksheet.GetRange("B1").SetValue(2014);
     * worksheet.GetRange("C1").SetValue(2015);
     * worksheet.GetRange("D1").SetValue(2016);
     * worksheet.GetRange("A2").SetValue("Projected Revenue");
     * worksheet.GetRange("A3").SetValue("Estimated Costs");
     * worksheet.GetRange("B2").SetValue(200);
     * worksheet.GetRange("B3").SetValue(250);
     * worksheet.GetRange("C2").SetValue(240);
     * worksheet.GetRange("C3").SetValue(260);
     * worksheet.GetRange("D2").SetValue(280);
     * worksheet.GetRange("D3").SetValue(280);
     * let chart = worksheet.AddChart("'Sheet1'!$A$1:$D$3", true, "comboBarLine", 2, 100 * 36000, 70 * 36000, 0, 2 * 36000, 5, 3 * 36000);
     * chart.SetTitle("Financial Overview", 13);
     * let fill = Api.CreateSolidFill(Api.RGB(51, 51, 51));
     * chart.SetSeriesFill(fill, 0, false);
     * fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * chart.SetSeriesFill(fill, 1, false);
     * let series = chart.GetSeries(0);
     * let seriesType = series.GetChartType();
     * worksheet.GetRange("F1").SetValue("Old Series Type = " + seriesType);
     * series.ChangeChartType("area");
     * seriesType = series.GetChartType();
     * worksheet.GetRange("F2").SetValue("New Series Type = " + seriesType);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiChartSeries/Methods/ChangeChartType/
     */
    ChangeChartType(sType: ChartType): boolean;

    /**
     * Returns a chart type of the current series.
     *
     * @example
     * ```js
     * // How do I find out what chart style a particular series is using in a spreadsheet?
     *
     * // Retrieve a series chart type and write the result to a cell in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * worksheet.GetRange("B1").SetValue(2014);
     * worksheet.GetRange("C1").SetValue(2015);
     * worksheet.GetRange("D1").SetValue(2016);
     * worksheet.GetRange("A2").SetValue("Projected Revenue");
     * worksheet.GetRange("A3").SetValue("Estimated Costs");
     * worksheet.GetRange("B2").SetValue(200);
     * worksheet.GetRange("B3").SetValue(250);
     * worksheet.GetRange("C2").SetValue(240);
     * worksheet.GetRange("C3").SetValue(260);
     * worksheet.GetRange("D2").SetValue(280);
     * worksheet.GetRange("D3").SetValue(280);
     * let chart = worksheet.AddChart("'Sheet1'!$A$1:$D$3", true, "comboBarLine", 2, 100 * 36000, 70 * 36000, 0, 2 * 36000, 5, 3 * 36000);
     * chart.SetTitle("Financial Overview", 13);
     * let fill = Api.CreateSolidFill(Api.RGB(51, 51, 51));
     * chart.SetSeriesFill(fill, 0, false);
     * fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * chart.SetSeriesFill(fill, 1, false);
     * let series = chart.GetSeries(0);
     * let seriesType = series.GetChartType();
     * worksheet.GetRange("F1").SetValue("Series Type = " + seriesType);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiChartSeries/Methods/GetChartType/
     */
    GetChartType(): ChartTypeLegacy;

    /**
     * Returns a type of the ApiChartSeries class.
     *
     * @example
     * ```js
     * // How do I check what kind of object a chart series belongs to in a spreadsheet?
     *
     * // Confirm the internal type of a chart series by reading its category in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     * worksheet.GetRange("B1").SetValue(2014);
     * worksheet.GetRange("C1").SetValue(2015);
     * worksheet.GetRange("D1").SetValue(2016);
     * worksheet.GetRange("A2").SetValue("Projected Revenue");
     * worksheet.GetRange("A3").SetValue("Estimated Costs");
     * worksheet.GetRange("B2").SetValue(200);
     * worksheet.GetRange("B3").SetValue(250);
     * worksheet.GetRange("C2").SetValue(240);
     * worksheet.GetRange("C3").SetValue(260);
     * worksheet.GetRange("D2").SetValue(280);
     * worksheet.GetRange("D3").SetValue(280);
     * let chart = worksheet.AddChart("'Sheet1'!$A$1:$D$3", true, "comboBarLine", 2, 100 * 36000, 70 * 36000, 0, 2 * 36000, 5, 3 * 36000);
     * chart.SetTitle("Financial Overview", 13);
     * let fill = Api.CreateSolidFill(Api.RGB(51, 51, 51));
     * chart.SetSeriesFill(fill, 0, false);
     * fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
     * chart.SetSeriesFill(fill, 1, false);
     * let series = chart.GetSeries(0);
     * let classType = series.GetClassType();
     * worksheet.GetRange("F1").SetValue("Class Type = " + classType);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiChartSeries/Methods/GetClassType/
     */
    GetClassType(): "chartSeries";

    /**
     * Returns a chart type of the current series using the chart type names from the {@link ChartType}
     * enumeration.
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiChartSeries/Methods/GetType/
     */
    GetType(): ChartType;
  }

