    /**
     * Modifies the current format condition with the specified parameters.
     *
     * @param Type - The format condition type.
     * @param Operator - The format condition operator.
     * @param Formula1 - The first formula.
     * @param Formula2 - The second formula.
     * @returns The modified format condition, or null if the rule does not exist.
     * @since 9.1.0
     *
     * @example
     * ```js
     * // How do I change what value or formula a conditional formatting rule checks for in a spreadsheet?
     *
     * // Replace the trigger condition of a formatting rule without removing it from a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     *
     * worksheet.GetRange("A1").SetValue("Sales Data");
     * worksheet.GetRange("A2").SetValue(30);
     * worksheet.GetRange("A3").SetValue(250);
     * worksheet.GetRange("A4").SetValue(150);
     * worksheet.GetRange("A5").SetValue(300);
     * worksheet.GetRange("A6").SetValue(40);
     *
     * let dataRange = worksheet.GetRange("A2:A6");
     *
     * let formatConditions = dataRange.GetFormatConditions();
     *
     * let condition1 = formatConditions.Add("xlCellValue", "xlLess", "50");
     * condition1.SetFillColor(Api.CreateColorFromRGB(255, 0, 0));
     *
     * worksheet.GetRange("C1").SetValue("Original formula:");
     * worksheet.GetRange("C2").SetValue(condition1.Formula1);
     *
     * condition1.Modify("xlCellValue", "xlGreater", "200");
     *
     * worksheet.GetRange("C4").SetValue("Modified formula:");
     * worksheet.GetRange("C5").SetValue(condition1.Formula1);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFormatCondition/Methods/Modify/
     */
    Modify(Type?: XlFormatConditionType, Operator?: XlFormatConditionOperator, Formula1?: string | number | ApiRange, Formula2?: string | number | ApiRange): ApiFormatCondition | null;

    /**
     * Sets the cell range to which the current conditional formatting rule applies.
     *
     * @param Range - The range to which the current conditional formatting rule will be applied.
     * @since 9.1.0
     *
     * @example
     * ```js
     * // How do I reassign a formatting rule to a different group of cells in a spreadsheet?
     *
     * // Expand or narrow the area where an existing formatting rule takes effect in a spreadsheet.
     *
     * let worksheet = Api.GetActiveSheet();
     *
     * worksheet.GetRange("A1").SetValue("Sales Data");
     * worksheet.GetRange("A2").SetValue(100);
     * worksheet.GetRange("A3").SetValue(250);
     * worksheet.GetRange("A4").SetValue(150);
     * worksheet.GetRange("A5").SetValue(300);
     * worksheet.GetRange("A6").SetValue(75);
     * worksheet.GetRange("A7").SetValue(180);
     * worksheet.GetRange("A8").SetValue(220);
     *
     * let dataRange = worksheet.GetRange("A2:A8");
     *
     * let formatConditions = dataRange.GetFormatConditions();
     *
     * let condition1 = formatConditions.Add("xlCellValue", "xlGreater", "200");
     * condition1.SetFillColor(Api.CreateColorFromRGB(255, 0, 0));
     *
     * worksheet.GetRange("C1").SetValue("Original range:");
     * worksheet.GetRange("C2").SetValue(condition1.GetAppliesTo().GetAddress());
     *
     * let newRange = worksheet.GetRange("A2:A5");
     * condition1.ModifyAppliesToRange(newRange);
     *
     * worksheet.GetRange("D1").SetValue("Modified range:");
     * worksheet.GetRange("D2").SetValue(condition1.GetAppliesTo().GetAddress());
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFormatCondition/Methods/ModifyAppliesToRange/
     */
